// Primitive members stored after their namespace object was created. Reads
// that provably run after the store read the stored literal; a read that can
// run before it (top-level code before the store, or any read once code has
// run before the store) stays a read.
var lib = lib || {};
lib.cfg = lib.cfg || {};
lib.cfg.EPS = 0.5;
lib.cfg.NAME = "v1";
lib.early = lib.cfg.LATE;
lib.cfg.LATE = 7;
lib.after = lib.cfg.LATE + 1;
lib.near = function (x) {
  return Math.abs(x) <= lib.cfg.EPS;
};
lib.name = function () {
  return lib.cfg.NAME + ":" + lib.cfg.LATE;
};
// Functions that read their own receiver, through an arrow, and not at all.
lib.counter = {
  n: 0,
  inc: function () {
    this.n++;
    return this.n;
  },
};
lib.twice = function (a) {
  return a * 2;
};
lib.tagOf = function () {
  const read = () => this.tag;
  return read();
};

// A store after a call: code ran before it, so no read folds.
var other = {};
other.log = [];
other.note = function (s) {
  other.log.push(s);
  return other.log.length;
};
other.seen = other.note("start");
other.flag = true;
other.check = function () {
  return other.flag;
};

module.exports = { lib, other };
